+export async function withRetry<T>(run: () => Promise<T>, attempts: number): Promise<T> {
+  let last: unknown = new Error("withRetry needs at least one attempt");
+  for (let i = 0; i < attempts; i++) {
+    try {
+      return await run();
+    } catch (error) {
+      last = error;
+    }
+  }
+  throw last;
+}
